/* MERGEN offline CodeMirror placeholder. Replace with vendored CodeMirror 5 build for production. */
(function(w){
  if (w.CodeMirror) return;
  function CM(textarea, opts){
    return {
      getValue:function(){ return textarea && textarea.value || ''; },
      setValue:function(v){ if(textarea) textarea.value = v || ''; },
      refresh:function(){},
      lineCount:function(){ var v = textarea && textarea.value || ''; return v ? v.split(/\n/).length : 1; },
      getWrapperElement:function(){ return textarea; }
    };
  }
  CM.fromTextArea = function(textarea, opts){ return CM(textarea, opts || {}); };
  CM.defineMode = function(){};
  CM.defineMIME = function(){};
  CM.commands = CM.commands || {};
  w.CodeMirror = CM;
})(window);
